import{_ as a,o as i,c as s,a2 as n}from"./chunks/framework.CqpfiAoK.js";const v=JSON.parse('{"title":"Ley de Garantía de Vivienda","description":"","frontmatter":{},"headers":[],"relativePath":"es/0045-住房保障法.md","filePath":"es/0045-住房保障法.md"}'),d={name:"es/0045-住房保障法.md"};function o(t,e,r,l,c,p){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ley-de-garantia-de-vivienda" tabindex="-1">Ley de Garantía de Vivienda <a class="header-anchor" href="#ley-de-garantia-de-vivienda" aria-label="Permalink to &quot;Ley de Garantía de Vivienda&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>45</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Derecho de residencia, Vivienda garantizada, Principios legales espaciales, Entorno habitable, Antiespeculación</td></tr></tbody></table><h2 id="i-proposito-legislativo-y-principios-basicos" tabindex="-1">I. Propósito Legislativo y Principios Básicos <a class="header-anchor" href="#i-proposito-legislativo-y-principios-basicos" aria-label="Permalink to &quot;I. Propósito Legislativo y Principios Básicos&quot;">​</a></h2><p>La <em>Ley de Garantía de Vivienda</em> es una de las cinco leyes complementarias de la Civilización Simbiótica del Ancla. Su objetivo es garantizar el derecho de residencia de todas las vidas dentro del Universo Hengyuan, establecer un sistema de garantía de vivienda justo y sostenible, utilizar la tecnología de despacho de principios legales espaciales para proporcionar espacios habitables adecuados a todas las razas, y prevenir la especulación y la depredación en el sector de la vivienda.</p><p>Esta Ley establece los siguientes principios básicos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Garantía de Residencia</td><td>Cada vida tiene derecho a obtener un espacio habitable adecuado; el estado y la civilización tienen la obligación de garantizar las necesidades básicas de residencia</td></tr><tr><td>Prioridad del Interés Público</td><td>La vivienda es primero una necesidad vital y no un bien especulativo; la vivienda garantizada tiene atributo de interés público</td></tr><tr><td>Eficiencia Espacial</td><td>Utilizar la tecnología de despacho de principios legales espaciales para mejorar la eficiencia de uso del espacio y ampliar el espacio habitable</td></tr><tr><td>Adaptación a Otras Razas</td><td>Proporcionar espacios habitables adaptados a las características fisiológicas y hábitos de vida de las distintas razas</td></tr><tr><td>Entorno Habitable</td><td>Los espacios habitables deben poseer un buen entorno ecológico, infraestructura y servicios públicos</td></tr><tr><td>Antiespeculación</td><td>Prohibir la especulación con la vivienda como objetivo, evitando que la vivienda se convierta en una herramienta para saquear la riqueza</td></tr></tbody></table><h2 id="ii-garantias-legales-del-derecho-de-residencia" tabindex="-1">II. Garantías Legales del Derecho de Residencia <a class="header-anchor" href="#ii-garantias-legales-del-derecho-de-residencia" aria-label="Permalink to &quot;II. Garantías Legales del Derecho de Residencia&quot;">​</a></h2><p>Esta Ley estipula explícitamente que el derecho de residencia es un derecho básico conferido a cada vida por la Constitución Simbiótica, que incluye específicamente:</p><ol><li><strong>Derecho Básico de Residencia</strong>: Cada vida tiene derecho a obtener un espacio habitable no inferior al estándar mínimo, determinado según el tamaño corporal y las necesidades de vida de cada raza.</li><li><strong>Derecho a Solicitar Vivienda Garantizada</strong>: Las vidas que cumplan las condiciones tienen derecho a solicitar vivienda garantizada, con condiciones de solicitud y estándares de asignación abiertos y transparentes.</li><li><strong>Derecho a la Seguridad de Residencia</strong>: Los espacios habitables deben cumplir estándares de seguridad; los edificios peligrosos y los espacios inadecuados no deben alquilarse ni asignarse.</li><li><strong>Derecho a la Estabilidad de Residencia</strong>: Los residentes de vivienda garantizada gozan de derechos de residencia estables al cumplir las condiciones y no deben ser desalojados arbitrariamente.</li><li><strong>Derecho al Entorno de Vida</strong>: Los residentes tienen derecho a obtener aire limpio, fuentes de agua y un buen entorno circundante, y derecho a presentar quejas sobre la contaminación ambiental.</li><li><strong>Derecho a la Renovación de Vivienda</strong>: Los residentes tienen derecho a renovar razonablemente su espacio habitable siempre que no se afecte la seguridad del edificio ni los derechos de otros.</li></ol><h2 id="iii-sistema-de-garantia-de-vivienda" tabindex="-1">III. Sistema de Garantía de Vivienda <a class="header-anchor" href="#iii-sistema-de-garantia-de-vivienda" aria-label="Permalink to &quot;III. Sistema de Garantía de Vivienda&quot;">​</a></h2><p>El sistema de garantía de vivienda de la Civilización Simbiótica del Ancla se divide en tres tipos de vivienda, cubriendo diferentes niveles de necesidad:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Nombre</th><th>Grupo Garantizado</th><th>Método de Asignación</th><th>Alquiler/Precio</th></tr></thead><tbody><tr><td>Primer tipo</td><td>Vivienda Pública de Alquiler</td><td>Grupos de bajos ingresos, cultivadores principiantes, nuevos inmigrantes</td><td>Sistema de solicitud y revisión, asignación por turnos</td><td>Alquiler bajo simbólico</td></tr><tr><td>Segundo tipo</td><td>Vivienda de Propiedad Compartida</td><td>Grupos de ingresos medios, cultivadores intermedios</td><td>Sistema de solicitud y revisión, asignación por sorteo</td><td>Bajo el precio de mercado, propiedad compartida entre individuo y estado</td></tr><tr><td>Tercer tipo</td><td>Vivienda Comercial</td><td>Grupos de altos ingresos, cultivadores avanzados</td><td>Transacción de mercado</td><td>Precio de mercado, sujeto a regulación</td></tr></tbody></table><p>Además, se utiliza la tecnología de despacho de principios legales espaciales para construir &quot;zonas residenciales de espacio plegado&quot;: ampliar la superficie residencial en un espacio físico limitado mediante la tecnología de plegado espacial, proporcionando más espacio habitable a las zonas de alta densidad. Las zonas residenciales de espacio plegado deben someterse a evaluación de seguridad para garantizar la estabilidad espacial.</p><h2 id="iv-adaptacion-de-vivienda-para-otras-razas" tabindex="-1">IV. Adaptación de Vivienda para Otras Razas <a class="header-anchor" href="#iv-adaptacion-de-vivienda-para-otras-razas" aria-label="Permalink to &quot;IV. Adaptación de Vivienda para Otras Razas&quot;">​</a></h2><p>Ante las necesidades especiales de residencia de las distintas razas dentro del Universo Hengyuan, esta Ley establece una institución de adaptación de vivienda para otras razas:</p><ul><li><strong>Razas acuáticas</strong>: Se proporcionan espacios habitables submarinos o residencias anfibias, equipados con sistemas de circulación de agua y mantenimiento de calidad del agua.</li><li><strong>Razas voladoras</strong>: Se proporcionan espacios habitables en altitud o residencias con plataformas de despegue y aterrizaje, equipados con gestión del tráfico aéreo.</li><li><strong>Vidas energéticas</strong>: Se proporcionan espacios habitables con concentración de energía adecuada, equipados con dispositivos de estabilización energética.</li><li><strong>Razas gigantes</strong>: Se proporcionan espacios habitables a gran escala, con estructuras de edificio especialmente reforzadas.</li><li><strong>Razas microscópicas</strong>: Se proporcionan zonas residenciales microscópicas, equipadas con pasajes de escala e instalaciones especiales.</li></ul><p>Los estándares de adaptación de vivienda para otras razas son formulados conjuntamente por la autoridad competente de vivienda junto con representantes de todas las razas, y se actualizan periódicamente.</p><h2 id="v-construccion-y-gestion-de-vivienda" tabindex="-1">V. Construcción y Gestión de Vivienda <a class="header-anchor" href="#v-construccion-y-gestion-de-vivienda" aria-label="Permalink to &quot;V. Construcción y Gestión de Vivienda&quot;">​</a></h2><ul><li><strong>Planificación de la Construcción de Vivienda</strong>: El estado formula planes de construcción de vivienda según el crecimiento poblacional y la inmigración, asegurando el equilibrio entre oferta y demanda.</li><li><strong>Estándares de Construcción</strong>: La construcción de vivienda garantizada debe cumplir estándares de seguridad, protección ambiental y habitabilidad; se prohíbe reducir la calidad de construcción.</li><li><strong>Gestión de Propiedad</strong>: Las zonas residenciales implementan un modelo que combina gestión autónoma y servicios profesionales de propiedad; los residentes tienen derecho a participar en las decisiones de gestión.</li><li><strong>Mantenimiento de Vivienda</strong>: El mantenimiento de la vivienda garantizada es responsabilidad de la institución de gestión de vivienda, con fondos provenientes de la acumulación pública.</li><li><strong>Mecanismo de Salida</strong>: Los residentes de vivienda garantizada cuyos ingresos o cultivo superen el estándar de garantía deben salir de la vivienda garantizada o pasar a vivienda comercial, otorgándose un período de transición razonable.</li></ul><h2 id="vi-antiespeculacion-y-supervision" tabindex="-1">VI. Antiespeculación y Supervisión <a class="header-anchor" href="#vi-antiespeculacion-y-supervision" aria-label="Permalink to &quot;VI. Antiespeculación y Supervisión&quot;">​</a></h2><p>Para prevenir la especulación y la depredación en el sector de la vivienda, esta Ley establece las siguientes medidas de supervisión:</p><ol><li>Limitar el número de viviendas comerciales en poder de los individuos; se aplican impuestos progresivos a la propiedad sobre los montos que superen el límite.</li><li>Prohibir el subarriendo y la reventa de la vivienda garantizada; los infractores pierden su elegibilidad de garantía y se les recupera la vivienda.</li><li>Establecer un sistema de información pública de transacciones de vivienda, evitando operaciones encubiertas y manipulación de precios.</li><li>Implementar gestión de cualificaciones y supervisión de fondos para los desarrolladores inmobiliarios, evitando proyectos inconclusos y fraudes.</li><li>Establecer mecanismos de quejas y resolución de disputas de vivienda, protegiendo los derechos e intereses legítimos de los residentes.</li></ol><h2 id="vii-responsabilidad-legal" tabindex="-1">VII. Responsabilidad Legal <a class="header-anchor" href="#vii-responsabilidad-legal" aria-label="Permalink to &quot;VII. Responsabilidad Legal&quot;">​</a></h2><p>Los actos que violen las disposiciones de esta Ley asumirán las siguientes responsabilidades según la gravedad de las circunstancias:</p><ul><li>Quienes asignen vivienda garantizada en violación de las normas serán ordenados a corregir y los responsables sancionados.</li><li>Quienes subarrienden o revendan vivienda garantizada perderán su elegibilidad de garantía, se les recuperará la vivienda y serán multados.</li><li>Los desarrolladores que reduzcan la calidad de construcción serán ordenados a rehacer los trabajos y multados; en casos graves, se revocan sus cualificaciones.</li><li>Quienes especulen con vivienda serán sujetos a altos impuestos de especulación y multas.</li><li>Quienes alquilen edificios peligrosos causando daño a los residentes asumirán responsabilidad de indemnización; en casos graves, se persigue responsabilidad penal.</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La <em>Ley de Garantía de Vivienda</em> es la implementación de la filosofía de &quot;un camino para todos&quot; de la Civilización Simbiótica del Ancla en el ámbito de la residencia. Al establecer un sistema clasificado de garantía de vivienda, utilizar tecnología de principios legales espaciales para ampliar el espacio habitable, adaptar las necesidades de residencia de otras razas y combatir la especulación inmobiliaria, garantiza que cada vida pueda tener un hogar seguro, adecuado y estable, proporcionando garantías de vivienda para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>39-住房与环境保障 (Vivienda y Protección Ambiental)</li><li>13-空间法理调度体系详解 (Explicación Detallada del Sistema de Despacho de Principios Legales Espaciales)</li><li>46-环境保护法 (Ley de Protección Ambiental)</li></ul>',29)])])}const b=a(d,[["render",o]]);export{v as __pageData,b as default};
